import{_ as e,c as i,o as l,ah as a,ao as p,ap as n}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"Pets in Heaven — Они, Небо и Ваше Горе","description":"Для тех, кто потерял питомца: что Библия говорит о животных, вечности и заботе Бога. Четыре бережных чтения.","frontmatter":{"title":"Pets in Heaven — Они, Небо и Ваше Горе","description":"Для тех, кто потерял питомца: что Библия говорит о животных, вечности и заботе Бога. Четыре бережных чтения."},"headers":[],"relativePath":"ru/pets-in-heaven/index.md","filePath":"ru/pets-in-heaven/index.md"}'),t={name:"ru/pets-in-heaven/index.md"};function o(r,s,c,d,v,h){return l(),i("div",null,[...s[0]||(s[0]=[a('<div class="pl-quote"><p>«После того как его не стало, я хотел знать только одно: ему сейчас хорошо? Мы ещё увидимся?»</p><p class="pl-quote-soft">Библия не отвечает на всё одной фразой — но даёт достаточно света, чтобы увидеть надежду в самой тёмной ночи.</p></div><section class="pl-section"><h2>Прежде чем начать</h2><p class="pl-lead">Это место не просит вас «поскорее пережить». Эти четыре текста — для вас, того, кто всё ещё скучает.</p><p>Потеря животного-друга — особое горе. Люди говорят: «это была просто собака» или «заведите другую» — но вы знаете, что это неправда. Он узнавал звук ваших шагов. В ваш самый трудный год он лежал у ваших ног. С ним ушёл первый взгляд, который встречал вас каждое утро.</p><p>Библия на самом деле говорит о животных много. Бог создал их, кормит их, заключает с ними завет и помещает их в мир, который обещает обновить. Эти стихи не доказывают, что «каждый питомец попадает в рай» — Библия такого не обещает — но они показывают что-то нежное: <strong>в Божьем замысле животные никогда не были чем-то, что можно выбросить.</strong></p><p>Пусть то, что вы здесь найдёте, будет не только стихами — пусть это будет Бог, помнящий даже воробья, помнящий и вашего.</p></section><section class="pl-section"><h2>Четыре чтения для вас</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/ru/pets-in-heaven/will-i-see-my-pet-again">Увижу ли я его снова?</a></h3><p>Надежда Библии для животных и неба — само творение ждёт искупления, и в новом творении остаются животные.</p><p class="pl-quote-soft">Римлянам 8:19-22 · Исаия 11:6-9 · Откровение 21:4-5</p></div><div class="pl-new-card"><h3><a href="/ru/pets-in-heaven/not-one-sparrow-forgotten">Ни один воробей не забыт</a></h3><p>Он был таким маленьким — вспомнит ли его мир? Иисус сказал: ни один воробей не падает без воли Отца.</p><p class="pl-quote-soft">Матфея 10:29-31 · Псалом 147:9 · Псалом 36:6</p></div><div class="pl-new-card"><h3><a href="/ru/pets-in-heaven/rainbow-bridge-covenant">По ту сторону Радужного моста</a></h3><p>«Радужный мост» — красивый образ, и в Библии действительно есть радуга: вечный завет Бога с <em>всяким живым существом</em>.</p><p class="pl-quote-soft">Бытие 9:9-13 · Исаия 65:25 · Откровение 5:13</p></div><div class="pl-new-card"><h3><a href="/ru/pets-in-heaven/permission-to-grieve">Разрешение горевать</a></h3><p>Бог хранит ваши слёзы в сосуде. Горе — не недостаток веры, а любовь, которая продолжается.</p><p class="pl-quote-soft">Псалом 56:8 · Псалом 34:18 · Матфея 5:4</p></div></div></section><section class="pl-section"><h2>Как читать</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>Медленно — не всё сразу</h3><p>Одного абзаца достаточно. Если стих заставил вас заплакать, остановитесь. Это не слабость, это движется любовь.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Подставьте его имя в стих</h3><p>Когда читаете «Он даёт пищу скоту», попробуйте произнести это имя. Бог так же заботился и о нём.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>Потом скажите ему одну фразу</h3><p>Не нужно красиво. Достаточно «я скучаю». Если хочется больше — дневник в PetLoss побудет рядом.</p></div></div></section><section class="pl-section"><h2>Все стихи в одном месте</h2><p class="pl-lead">Все отрывки, упомянутые в этих четырёх чтениях, собраны здесь — чтобы перечитывать и не спеша искать.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/ru/pets-in-heaven/will-i-see-my-pet-again">Увижу ли я его снова?</a></h3><ul class="pl-verse-list"><li>Римлянам 8:19-22</li><li>Исаия 11:6-9</li><li>Откровение 21:4-5</li><li>Псалом 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ru/pets-in-heaven/not-one-sparrow-forgotten">Ни один воробей не забыт</a></h3><ul class="pl-verse-list"><li>Матфея 10:29-31</li><li>Псалом 147:9</li><li>Псалом 36:6</li><li>Псалом 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/ru/pets-in-heaven/rainbow-bridge-covenant">По ту сторону Радужного моста</a></h3><ul class="pl-verse-list"><li>Бытие 9:9-13</li><li>Исаия 65:25</li><li>Откровение 5:13</li><li>Псалом 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ru/pets-in-heaven/permission-to-grieve">Разрешение горевать</a></h3><ul class="pl-verse-list"><li>Псалом 56:8</li><li>Псалом 34:18</li><li>Псалом 147:3</li><li>Матфея 5:4</li><li>Иоанна 11:35</li><li>Откровение 21:4</li></ul></div></div></section><div class="pl-cta"><h2>Пусть здесь вас бережно поддержат.</h2><p>Если вы хотите место, где можно хранить его фотографии и писать то, что не успели сказать, PetLoss тихо побудет с вами — без аккаунта, без загрузок, полностью офлайн.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Скачать в App Store</a><p class="pl-disclaimer">Эти тексты предлагают размышление о вере и эмоциональную поддержку; они не являются медицинской, психологической или терапевтической консультацией. Если горе долго мешает вам жить, обратитесь к лицензированному специалисту или в местную службу поддержки. Библейские цитаты — из King James Version (KJV).</p></div><div class="pl-bible"><h3>Пусть слово Писания остаётся с вами</h3><p>Все стихи в этих четырёх чтениях — из Библии. С приложением Rainbow Bible вы можете читать Писание в любое время и настроить виджет со стихом дня — небольшой свет для дней, когда вы скучаете.</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="Виджет Rainbow Bible со стихом 2 Тимофею 2:13" loading="lazy"><figcaption>Стих дня на главном экране</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible — тема «Питомцы на небесах» со стихом Матфея 10:29-31" loading="lazy"><figcaption>Читайте Писание в теме «Питомцы на небесах»</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Скачать Rainbow Bible в App Store</a></div>',7)])])}const f=e(t,[["render",o]]);export{m as __pageData,f as default};
